      "cpu": "AM4平台性价比6核，满足本地Whisper转写多线程需求",
      "gpu": "唯一符合非NVIDIA硬性要求的AMD显卡，12GB显存利于大模型推理",
      "motherboard": "B550芯片组兼容Ryzen 5000，双M.2扩展性好",
      "memory": "DDR4-3200 16GB双通道，兼顾带宽与成本",
      "ssd": "NVMe 1TB比SATA更快，适合音频素材和模型加载",
      "psu": "650W铜牌足够CPU+GPU功耗，双8pin接口匹配7700XT",
      "case": "MATX机箱紧凑且支持240冷排/塔式散热",
      "cooler": "AG400标称散热能力220W，覆盖65W TDP的R5 5500有充足余量"
    }
  },
  "assessments": [
